package cn.zhuatech.cronops.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CronAnalysisService{public Result analyze(Request r){String[] p=r.expression().trim().split("\\s+");if(p.length!=5)return new Result(false,0,0,"INVALID",List.of("仅支持标准五段式 Cron 表达式"));int interval=minutes(p[0]);if(interval<1)return new Result(false,0,0,"INVALID",List.of("分钟字段仅支持 *、*/N 或 0-59"));int daily=1440/interval;double load=daily*r.averageRunMinutes()/(1440.0*r.maxConcurrency())*100;List<String>w=new ArrayList<>();if(load>80)w.add("任务预计占用大部分可用执行容量");if(!r.idempotent()&&daily>24)w.add("高频任务应确保重复执行幂等");if(!r.failureAlertEnabled())w.add("建议配置连续失败告警");String status=load>100?"THROTTLE":load>70||!r.idempotent()||!r.failureAlertEnabled()?"REVIEW":"SAFE";if(w.isEmpty())w.add("执行频次和运行容量处于安全范围");return new Result(true,interval,daily,status,w);}
 private int minutes(String v){if(v.equals("*"))return 1;if(v.matches("\\*/([1-9]|[1-5][0-9])"))return Integer.parseInt(v.substring(2));if(v.matches("[0-5]?\\d"))return 60;return -1;}
 public record Request(@NotBlank String expression,@DecimalMin("0.01") double averageRunMinutes,@Min(1) int maxConcurrency,@NotNull Boolean idempotent,@NotNull Boolean failureAlertEnabled){}public record Result(boolean valid,int intervalMinutes,int estimatedRunsPerDay,String status,List<String>warnings){} }
